// Cuenta corriente de un cliente (datos inventados, en pesos). El saldo NO se guarda: se calcula con los eventos.
class Almacen {
  constructor() { this.flujos = new Map(); }
  leer(cuenta) { return this.flujos.get(cuenta) ?? []; }
  // versionEsperada = cuántos eventos creía haber visto quien escribe. Si no coincide, alguien se le adelantó.
  agregar(cuenta, eventos, versionEsperada) {
    const f = this.leer(cuenta);
    if (f.length !== versionEsperada) throw new Error(`conflicto: esperaba v${versionEsperada}, ya hay v${f.length}`);
    this.flujos.set(cuenta, [...f, ...eventos.map((e, i) => ({ ...e, v: f.length + i + 1 }))]);
  }
}

// Cómo cambia el estado con cada evento. Función pura: mismo estado y mismo evento, mismo resultado.
function aplicar(s, e) {
  switch (e.tipo) {
    case 'CuentaAbierta':        return { ...s, abierta: true };
    case 'FacturaEmitida':       return { ...s, saldo: s.saldo + e.monto };
    case 'PagoRecibido':         return { ...s, saldo: s.saldo - e.monto };
    case 'NotaDeCreditoEmitida': return { ...s, saldo: s.saldo - e.monto };
    default:                     return s;
  }
}
const estado = (eventos) => eventos.reduce(aplicar, { saldo: 0, abierta: false });

// Comando: decide con el estado reconstruido y, si corresponde, agrega UN evento nuevo.
function registrarPago(almacen, cuenta, monto, fecha) {
  const f = almacen.leer(cuenta); const s = estado(f);
  if (!s.abierta) throw new Error('la cuenta no existe');
  if (monto > s.saldo) throw new Error(`el pago ($${monto}) supera el saldo ($${s.saldo})`);
  almacen.agregar(cuenta, [{ tipo: 'PagoRecibido', monto, fecha }], f.length);
}

const a = new Almacen(); const C = 'Ferretería Sur';
a.agregar(C, [
  { tipo: 'CuentaAbierta', fecha: '2026-10-01' },
  { tipo: 'FacturaEmitida', monto: 120000, fecha: '2026-10-03' },
  { tipo: 'PagoRecibido', monto: 50000, fecha: '2026-10-10' },
  { tipo: 'FacturaEmitida', monto: 80000, fecha: '2026-10-20' },
  { tipo: 'NotaDeCreditoEmitida', monto: 20000, fecha: '2026-10-25' },
  { tipo: 'PagoRecibido', monto: 60000, fecha: '2026-11-02' },
], 0);

console.log('saldo hoy:', estado(a.leer(C)).saldo);
console.log('saldo al 15/10:', estado(a.leer(C).filter((e) => e.fecha <= '2026-10-15')).saldo);

// Dos operarios miran la cuenta a la vez (v6) e intentan pagar el saldo completo.
const vistaB = a.leer(C).length;
registrarPago(a, C, 70000, '2026-11-10');
try { a.agregar(C, [{ tipo: 'PagoRecibido', monto: 70000, fecha: '2026-11-10' }], vistaB); }
catch (err) { console.log('segundo operario:', err.message); }
try { registrarPago(a, C, 1, '2026-11-11'); } catch (err) { console.log('pago de más:', err.message); }
console.log('eventos en el flujo:', a.leer(C).length, '| saldo ahora:', estado(a.leer(C)).saldo);

// Lado de lectura: proyecciones que se arman leyendo el registro de eventos (datos inventados, en pesos).
const registro = [
  { cuenta: 'Ferretería Sur',  tipo: 'FacturaEmitida',       monto: 120000, fecha: '2026-10-03' },
  { cuenta: 'Kiosco Norte',    tipo: 'FacturaEmitida',       monto: 45000,  fecha: '2026-10-04' },
  { cuenta: 'Ferretería Sur',  tipo: 'PagoRecibido',         monto: 50000,  fecha: '2026-10-10' },
  { cuenta: 'Librería Oeste',  tipo: 'FacturaEmitida',       monto: 90000,  fecha: '2026-10-12' },
  { cuenta: 'Ferretería Sur',  tipo: 'FacturaEmitida',       monto: 80000,  fecha: '2026-10-20' },
  { cuenta: 'Ferretería Sur',  tipo: 'NotaDeCreditoEmitida', monto: 20000,  fecha: '2026-10-25' },
  { cuenta: 'Kiosco Norte',    tipo: 'PagoRecibido',         monto: 45000,  fecha: '2026-10-28' },
