  { cuenta: 'Ferretería Sur',  tipo: 'PagoRecibido',         monto: 60000,  fecha: '2026-11-02' },
  { cuenta: 'Librería Oeste',  tipo: 'PagoRecibido',         monto: 40000,  fecha: '2026-11-09' },
];

class Proyeccion {
  constructor(nombre, aplicar) { this.nombre = nombre; this.aplicar = aplicar; this.reiniciar(); }
  reiniciar() { this.pos = 0; this.vista = {}; }
  avanzar(log, hasta = log.length) { while (this.pos < hasta) this.aplicar(this.vista, log[this.pos++]); }
  reconstruir(log) { this.reiniciar(); this.avanzar(log); }
}

// Proyección 1, con un error: se olvida de las notas de crédito.
const saldos = new Proyeccion('saldos', (v, e) => {
  const signo = e.tipo === 'FacturaEmitida' ? 1 : e.tipo === 'PagoRecibido' ? -1 : 0; // error: falta NotaDeCreditoEmitida
  v[e.cuenta] = (v[e.cuenta] ?? 0) + signo * e.monto;
});
saldos.avanzar(registro);
console.log('saldos con el error:', JSON.stringify(saldos.vista));

// Se corrige el código y se reconstruye desde cero con el mismo registro.
saldos.aplicar = (v, e) => {
  const signo = e.tipo === 'FacturaEmitida' ? 1 : e.tipo === 'NotaDeCreditoEmitida' || e.tipo === 'PagoRecibido' ? -1 : 0;
  v[e.cuenta] = (v[e.cuenta] ?? 0) + signo * e.monto;
};
saldos.reconstruir(registro);
console.log('saldos corregidos:  ', JSON.stringify(saldos.vista));

// Una pregunta nueva, meses después: ¿cuánto se facturó por mes? Nadie toca el lado de escritura: se arma con el historial.
const porMes = new Proyeccion('facturadoPorMes', (v, e) => {
  if (e.tipo === 'FacturaEmitida') v[e.fecha.slice(0, 7)] = (v[e.fecha.slice(0, 7)] ?? 0) + e.monto;
});
porMes.avanzar(registro);
console.log('facturado por mes:  ', JSON.stringify(porMes.vista));

// Atraso: se agrega un evento nuevo al registro y la proyección todavía no lo leyó.
registro.push({ cuenta: 'Kiosco Norte', tipo: 'FacturaEmitida', monto: 25000, fecha: '2026-11-12' });
console.log('Kiosco Norte, antes de avanzar:', saldos.vista['Kiosco Norte'], '| atraso:', registro.length - saldos.pos, 'evento');
saldos.avanzar(registro);
console.log('Kiosco Norte, después:         ', saldos.vista['Kiosco Norte'], '| atraso:', registro.length - saldos.pos);

// La versión 1 de «FacturaEmitida» guardaba solo el monto total. La versión 2 separa neto e IVA.
// Los eventos viejos no se reescriben: se traducen al leerlos (upcasting), de a una versión por vez.
const ALICUOTA = 0.21; // alícuota de ejemplo

function subirVersion(e) {
  if (e.tipo === 'FacturaEmitida' && e.version === 1) {
    const neto = Math.round(e.monto / (1 + ALICUOTA));
    return { ...e, version: 2, neto, iva: e.monto - neto };
  }
  return e;
}
const actualizar = (e) => { let x = e; while (true) { const y = subirVersion(x); if (y === x) return x; x = y; } };

const guardados = [
  { tipo: 'FacturaEmitida', version: 1, monto: 121000, fecha: '2026-03-01' },            // escrito hace meses
  { tipo: 'FacturaEmitida', version: 2, monto: 60500, neto: 50000, iva: 10500, fecha: '2026-11-05' }, // escrito hoy
];
for (const e of guardados) console.log(JSON.stringify(actualizar(e)));
console.log('lo guardado sigue igual:', JSON.stringify(guardados[0]));
